use std::collections::HashSet;

fn has_common_element(list1: &Vec<i32>, list2: &Vec<i32>) -> bool {
    // If either list is empty, return false
    if list1.is_empty() || list2.is_empty() {
        return false;
    }

    // Create a HashSet from the first list
    let set: HashSet<&i32> = list1.iter().collect();

    // Check if any element in the second list exists in the HashSet
    for &element in list2 {
        if set.contains(&element) {
            return true; // Found a common element
        }
    }

    false // No common elements found
}

// The contains function is not strictly necessary for the main task,
// but we can implement it as a utility function if needed.
fn contains(list: &Vec<i32>, element: i32) -> bool {
    list.iter().any(|&x| x == element)
}